"""Patch a Stunt Car Racer ADF for 68060 emulation, PAL 50 FPS or NTSC 60 FPS,
or write a WHDLoad install of the patched game.

Self-contained: Python 3.8+ and the supported original ADF are sufficient.
Selectable 20–30 ms physics and 50 FPS rendering for Practice, computer-opponent
and linked two-player races.
"""
import argparse
import hashlib
import os
from pathlib import Path
import shutil
import struct
import tempfile

VERSION = '1.6.0'
OUTPUT_NAME = f'StuntCarRacer-Performance-v{VERSION}.adf'
SOURCE_SHA256 = '548fd106cd62f2d80159d48ddd5293d8b22b6b17f80c17a84a61d75f5c8a9e06'
DISK_SIZE = 901120
PAYLOAD_OFFSET = 0xb720
INTRO_OFFSET = 0x74000
INTRO_RESERVED_SIZE = 8192


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def boot_sum(data):
    """Amiga end-around-carry sum of the two boot sectors."""
    total = 0
    for (word,) in struct.iter_unpack('>I', data[:1024]):
        total += word
        total = (total & 0xffffffff) + (total >> 32)
    return total


def patch_performance_disk(source):
    if len(source) != DISK_SIZE or sha256(source) != SOURCE_SHA256:
        raise ValueError('Unsupported original ADF: expected SHA-256 ' + SOURCE_SHA256)
    boot = bytes.fromhex(BOOT_HEX)
    runtime = bytes.fromhex(RUNTIME_HEX)
    if sha256(boot) != BOOT_SHA256 or sha256(runtime) != RUNTIME_SHA256:
        raise ValueError('Embedded patch is corrupt')
    intro = bytes.fromhex(INTRO_HEX)
    if len(intro) > INTRO_RESERVED_SIZE or sha256(intro) != INTRO_SHA256:
        raise ValueError('Embedded intro is corrupt')
    result = bytearray(source)

    def replace(offset, expected, new):
        if len(expected) != len(new) or source[offset:offset + len(new)] != expected:
            raise ValueError('Original bytes differ at ADF offset 0x%x' % offset)
        result[offset:offset + len(new)] = new

    for offset, original, replacement in BOOT_HOOKS:
        replace(offset, bytes.fromhex(original), bytes.fromhex(replacement))
    replace(0x200, bytes(len(boot)), boot)
    original_tail = source[PAYLOAD_OFFSET:PAYLOAD_OFFSET + len(runtime)]
    if sha256(original_tail) != TAIL_SHA256:
        raise ValueError('Unexpected loader tail')
    replace(PAYLOAD_OFFSET, original_tail, runtime)
    replace(INTRO_OFFSET, bytes(INTRO_RESERVED_SIZE), intro + bytes(INTRO_RESERVED_SIZE - len(intro)))
    for offset, original, replacement in HOOKS:
        replace(offset, bytes.fromhex(original), bytes.fromhex(replacement))
    result[4:8] = bytes(4)
    struct.pack_into('>I', result, 4, boot_sum(result) ^ 0xffffffff)
    if boot_sum(result) != 0xffffffff or sha256(result) != PERFORMANCE_SHA256:
        raise ValueError('Patched ADF verification failed')
    return bytes(result)


def patch_disk(source):
    """Apply the guarded performance layer, then the complete track editor."""
    result = bytearray(patch_performance_disk(source))
    for offset, old_hex, new_hex in EDITOR_CHANGES:
        old, new = bytes.fromhex(old_hex), bytes.fromhex(new_hex)
        if len(old) != len(new) or result[offset:offset + len(old)] != old:
            raise ValueError('Editor source bytes differ at ADF offset 0x%x' % offset)
        result[offset:offset + len(new)] = new
    if boot_sum(result) != 0xffffffff or sha256(result) != OUTPUT_SHA256:
        raise ValueError('Editor ADF verification failed')
    return bytes(result)


def default_output_path(source_path):
    return Path(source_path).with_name(OUTPUT_NAME)


def write_disk(source_path, output_path, force=False):
    source_path = Path(source_path).expanduser()
    output_path = Path(output_path).expanduser()
    if source_path.resolve() == output_path.resolve():
        raise ValueError('The original ADF must not be overwritten')
    if output_path.exists() and source_path.samefile(output_path):
        raise ValueError('The original ADF must not be overwritten (same file)')
    if output_path.is_symlink():
        raise ValueError('Output must not be a symbolic link: ' + str(output_path))
    if output_path.exists() and not force:
        raise FileExistsError('Output already exists (use --force): ' + str(output_path))
    patched = patch_disk(source_path.read_bytes())
    output_path.parent.mkdir(parents=True, exist_ok=True)
    # Verify the complete temporary file before publishing. Without --force,
    # link also protects a destination created after the existence check.
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(dir=output_path.parent, prefix='.stunt-', delete=False) as f:
            temporary = Path(f.name)
            f.write(patched)
            f.flush()
            os.fsync(f.fileno())
        if temporary.read_bytes() != patched:
            raise ValueError('Written ADF verification failed')
        if force:
            os.replace(temporary, output_path)
            temporary = None
        else:
            os.link(temporary, output_path)
    finally:
        if temporary is not None:
            temporary.unlink()
    return sha256(patched)


WHDLOAD_SLAVE_NAME = 'StuntCarRacer.slave'
WHDLOAD_ICON_NAME = 'StuntCarRacer.info'


def whdload_install(source):
    """The files of the WHDLoad install of the patched disk, by name."""
    disk = patch_disk(source)
    slave = bytes.fromhex(WHDLOAD_SLAVE_HEX)
    icon = bytes.fromhex(WHDLOAD_ICON_HEX)
    if sha256(slave) != WHDLOAD_SLAVE_SHA256 or sha256(icon) != WHDLOAD_ICON_SHA256:
        raise ValueError('Embedded WHDLoad files are corrupt')
    return {WHDLOAD_SLAVE_NAME: slave, 'Disk.1': disk, WHDLOAD_ICON_NAME: icon}


def whdload_drawer_icon():
    """The Workbench drawer icon of the install directory."""
    drawer = bytes.fromhex(WHDLOAD_DRAWER_HEX)
    if sha256(drawer) != WHDLOAD_DRAWER_SHA256:
        raise ValueError('Embedded WHDLoad files are corrupt')
    return drawer


def publish_whdload(output_dir, files, drawer):
    """Create the install directory with these files, and its drawer icon next
    to it (the directory's name + .info). Exclusive creation never replaces
    anything and needs no hard links, so FAT-formatted media work as well;
    a failed install removes what it created."""
    output_dir = Path(output_dir)
    drawer_path = output_dir.parent / (output_dir.name + '.info')
    for path in (output_dir, drawer_path):
        if path.exists():
            raise FileExistsError('Output already exists: ' + str(path))
    created = []
    try:
        with open(drawer_path, 'xb') as f:
            created.append(drawer_path)
            f.write(drawer)
        output_dir.mkdir()
        created.append(output_dir)
        for name, data in files.items():
            (output_dir / name).write_bytes(data)
    except BaseException:
        if output_dir in created:
            shutil.rmtree(output_dir, ignore_errors=True)
        if drawer_path in created:
            try:
                drawer_path.unlink()
            except OSError:
                pass
        raise


def write_whdload(source_path, output_dir):
    """Write a new WHDLoad install of the original disk; returns Disk.1's SHA-256."""
    files = whdload_install(Path(source_path).expanduser().read_bytes())
    publish_whdload(Path(output_dir).expanduser(), files, whdload_drawer_icon())
    return sha256(files['Disk.1'])


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('original', type=Path, help='Unmodified supported Stunt Car Racer ADF')
    target = parser.add_mutually_exclusive_group()
    target.add_argument('-o', '--output', type=Path,
                        help='Output ADF (default: %s beside original)' % OUTPUT_NAME)
    target.add_argument('--whdload', type=Path, metavar='DIRECTORY',
                        help='Write a WHDLoad install to this new directory, '
                             'and its drawer icon next to it, instead of an ADF')
    parser.add_argument('-f', '--force', action='store_true',
                        help='Replace an existing output ADF; never overwrite the original')
    parser.add_argument('--version', action='version', version='%(prog)s ' + VERSION)
    args = parser.parse_args(argv)
    if args.whdload is not None and args.force:
        parser.error('--force does not apply to --whdload; an existing install is never replaced')
    try:
        if args.whdload is not None:
            digest = write_whdload(args.original, args.whdload)
        else:
            output = args.output if args.output is not None else default_output_path(args.original)
            digest = write_disk(args.original, output, force=args.force)
    except (OSError, ValueError) as error:
        parser.exit(1, 'Error: %s\n' % error)
    print('Stunt Car Racer 50 FPS patch ' + VERSION)
    if args.whdload is not None:
        directory = args.whdload.expanduser()
        print('Created WHDLoad install %s and its drawer icon %s.info' % (directory, directory))
        print('Disk.1 SHA-256: %s' % digest)
        print('Start the icon or: WHDLoad StuntCarRacer.slave PRELOAD NOWRITECACHE. '
              '68060, 2 MiB Chip, at least 2 MiB Fast RAM, WHDLoad 17 or later.')
        return
    print('Created %s\nSHA-256: %s' % (output, digest))
    print('Practice and computer-opponent races: PAL or NTSC 68060 emulation, 2 MiB Chip, at least 1 MiB Fast RAM; linked races: PAL.')


